import ReactPlayer from 'react-player';
import { 처리중Context } from '~/widgets/exchange-convert-to-token-funnel/model/schemas';
import { useSetHeaderLeft } from '~/widgets/sub-layout/use-sub-layout';
import { useExchangeProcessVideo } from '~/features/load-video/use-exchange-process-video';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { DepositRequestDTO } from '~/entities/exchange/api/dtos/types';
import { useResultSearchMutation } from '~/entities/exchange/api/hooks/use-result-search-mutation';
import { useConvertToTokenExecuteTrnscMutation } from '~/entities/exchange/api/hooks/use-transfer-deposit-execute-trnsc-mutation';
import { useConvertToTokenMutation } from '~/entities/exchange/api/hooks/use-transfer-deposit-mutation';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { statusHandlers } from '~/entities/exchange-process/lib/use-transaction-status';
import { findTokenItemById, getTokenItemLabel } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import i18n from '~/shared/i18n/i18n';

type ProcessPageProps = {
  context: 처리중Context;
  onNext: (params: { trnscId: string; reqAliasNm: string }) => void;
  onError: (error: Error) => void;
};

export const ProcessPage = ({ onNext, onError, context }: ProcessPageProps) => {
  const { movUrl } = useExchangeProcessVideo({ trnscTypeCd: context.trnscTypeCd });
  const { mutateAsync: convertToToken } = useConvertToTokenMutation();
  const { mutateAsync: convertToTokenExecuteTrnsc } = useConvertToTokenExecuteTrnscMutation();
  const { mutateAsync: resultSearch } = useResultSearchMutation({ throwOnError: false });
  const { data: userRes } = useGetUserInfoQuery();

  /**
   * 입금 전환 요청 처리 함수
   */
  const requestConvertToToken = async () => {
    const params: DepositRequestDTO = {
      tbAcnutMastr: {
        cstmrNo: userRes?.tbCstmrMastr?.cstmrNo ?? '',
        trnscAmt: context.trnscAmt,
      },
    };
    return await convertToToken(params);
  };

  const executeConvertToToken = async () => {
    return await convertToTokenExecuteTrnsc(context.txCd);
  };

  /**
   * 비디오 종료 후 호출되는 이벤트 핸들러
   */
  const handleEventChange = async () => {
    try {
      // 입금 전환 API 호출
      const requestResult = await executeConvertToToken();

      // 트랜잭션 ID가 문자열인 경우 폴링 시작
      if (requestResult && typeof requestResult.requestId === 'string') {
        // await pollTransactionStatus({
        //   transactionId: requestResult,
        //   resultSearch,
        //   openAlertDialog,
        //   onNext,
        //   onError,
        //   counter: count,
        // });
        const handlers = statusHandlers(requestResult.requestId, requestResult.payload?.aliasNm ?? '', {
          onNext,
          onError,
        });

        // Execute the appropriate handler based on status or use default
        handlers[requestResult?.status as keyof typeof handlers]();
      } else {
        const error = new Error('전환입금 오류');
        onError(error);
      }
    } catch (error) {
      onError(error instanceof Error ? error : new Error('Failed to process convert to token'));
    }
  };

  useSetHeaderLeft(<></>);

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);
  const tokenItem = findTokenItemById(userRes?.tbCstmrMastr?.tokenList, context.tokenId);
  const usingTokenLabel = getTokenItemLabel(tokenItem);
  const tokenBankCode = tokenItem?.bankCd;
  const { shortBankName: tokenBankShortName } = useComBankInfo(tokenBankCode);
  const tokenBankLabel = tokenBankShortName ?? '';

  return (
    <div className="wrap bgw">
      <div className="content sub">
        <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Process} transactionLabel={transactionLabel}>
          <div className="whitespace-pre-wrap">
            {i18n.t('text:linkedAccountFromAAndBToCAndD', {
              a: tokenBankLabel,
              b: userRes?.tbCstmrMastr?.realAcnutNo,
              c: usingTokenLabel,
              d: tokenBankLabel,
            })}
          </div>
        </ConfirmInfo>
        <div className="result-area">
          <div className="process">
            <div className="process-mov">
              <ReactPlayer
                url={movUrl}
                width="250px"
                height="250px"
                playing={true}
                muted={true}
                controls={false}
                loop={false}
                onEnded={handleEventChange}
                config={{
                  file: {
                    attributes: {
                      playsInline: true, // Prevents fullscreen on iOS
                    },
                  },
                }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
